-- 사건 세부 분야 4종 추가 — 폭력·테러(POLITICAL_VIOLENCE, 정치 폭력) · 사법·재판(JUSTICE) · 치안·체포·구금(ARREST_DETENTION) · 범죄(CRIME).
-- PROTEST_VIOLENCE는 값 그대로 이름만 '시위·집회·소요'로 좁힌다(겨눈 폭력·테러는 POLITICAL_VIOLENCE로).
-- 값 추가만이라 기존 행은 그대로다(재분류는 데이터 작업으로 따로).

-- AlterTable
ALTER TABLE `event` MODIFY `type` ENUM('WAR', 'WAR_DECLARATION', 'BATTLE', 'UPRISING', 'ATTACK', 'PROTEST_VIOLENCE', 'POLITICAL_VIOLENCE', 'MOBILIZATION', 'MILITARY_FORMATION', 'TREATY', 'SUMMIT', 'DECLARATION', 'VISIT', 'CRISIS', 'EXPANSION', 'STATEHOOD', 'TERRITORY', 'POWER_CHANGE', 'POWER_STRUGGLE', 'ELECTION', 'LAW_POLICY', 'INSTITUTION', 'INCIDENT', 'MOVEMENT', 'PARTY_RALLY', 'JUSTICE', 'ARREST_DETENTION', 'CRIME', 'COMPANY', 'MARKET', 'PRODUCT', 'CONSTRUCTION', 'DISASTER', 'DISCOVERY', 'CREATION', 'PRESS_PUBLICATION', 'CONVERSION', 'MIGRATION', 'PERSONAL') NULL;

-- AlterTable
ALTER TABLE `event_series` MODIFY `default_event_type` ENUM('WAR', 'WAR_DECLARATION', 'BATTLE', 'UPRISING', 'ATTACK', 'PROTEST_VIOLENCE', 'POLITICAL_VIOLENCE', 'MOBILIZATION', 'MILITARY_FORMATION', 'TREATY', 'SUMMIT', 'DECLARATION', 'VISIT', 'CRISIS', 'EXPANSION', 'STATEHOOD', 'TERRITORY', 'POWER_CHANGE', 'POWER_STRUGGLE', 'ELECTION', 'LAW_POLICY', 'INSTITUTION', 'INCIDENT', 'MOVEMENT', 'PARTY_RALLY', 'JUSTICE', 'ARREST_DETENTION', 'CRIME', 'COMPANY', 'MARKET', 'PRODUCT', 'CONSTRUCTION', 'DISASTER', 'DISCOVERY', 'CREATION', 'PRESS_PUBLICATION', 'CONVERSION', 'MIGRATION', 'PERSONAL') NULL DEFAULT 'SUMMIT';
